int punkte = 62;

// Lange Version mit if/else:
string ergebnis;
if (punkte >= 50)
{
    ergebnis = "bestanden";
}
else
{
    ergebnis = "nicht bestanden";
}

// Kurze Version mit dem ternären Operator:
string ergebnis2 = punkte >= 50 ? "bestanden" : "nicht bestanden";

Console.WriteLine(ergebnis);
Console.WriteLine(ergebnis2);
// Ausgabe:
// bestanden
// bestanden

int anzahl = 1;
int a = 8;
int b = 13;

Console.WriteLine($"Im Korb liegt {anzahl} {(anzahl == 1 ? "Apfel" : "Äpfel")}.");

int groesser = a > b ? a : b;
Console.WriteLine($"Die größere Zahl ist {groesser}.");
// Ausgabe:
// Im Korb liegt 1 Apfel.
// Die größere Zahl ist 13.

bool hatTicket = true;
int alter = 12;

if (hatTicket)
{
    if (alter >= 16)
    {
        Console.WriteLine("Viel Spaß im Film!");
    }
    else
    {
        Console.WriteLine("Der Film ist erst ab 16.");
    }
}
else
{
    Console.WriteLine("Bitte zuerst ein Ticket kaufen.");
}
// Ausgabe: Der Film ist erst ab 16.

int temperatur = 15;

if (temperatur > 25)
    Console.WriteLine("Ab ins Freibad!");
    Console.WriteLine("Sonnencreme nicht vergessen!");  // gehört NICHT zum if

// Ausgabe: Sonnencreme nicht vergessen!

int alter = 15;
string gruppe = alter < 14 ? "Kind" : alter < 18 ? "Jugendlich" : "Erwachsen";
Console.WriteLine(gruppe);
// Ausgabe: Jugendlich

